"""Local review gallery; no network dependencies."""
import sys,json,html
from pathlib import Path
out=Path(sys.argv[1]).resolve(); specs=json.loads((out/'experiments.json').read_text()); cards=[]
for i,s in enumerate(specs):
 folder=Path(s['visual_asset']).parent.as_posix();title=html.escape(s['name']);action=html.escape(s['one_robot_action'])
 cards.append(f'''<section id="candidate-{i+1}"><h2>{i+1:02d} · {title}</h2><p>{action}</p><div class="views"><figure><img loading="lazy" src="{folder}/Front_ART_PREVIEW.png" alt="{title}, front camera"><figcaption>Fixed front camera</figcaption></figure><figure><img loading="lazy" src="{folder}/Overhead_ART_PREVIEW.png" alt="{title}, overhead camera"><figcaption>Fixed overhead camera</figcaption></figure></div><p class="files"><a href="{folder}/ART_PREVIEW.blend">Editable preview</a> · <a href="{folder}/Environment.blend">Environment project</a> · <a href="{folder}/Experiment.usdc">USD</a> · <a href="{folder}/manifest.json">Geometry and cameras</a></p></section>''')
nav=' '.join(f'<a href="#candidate-{i+1}">{i+1:02d}</a>' for i in range(6))
(out/'CANDIDATES.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>OpenArms experiment candidates</title><style>body{font:16px/1.5 system-ui,sans-serif;margin:0;background:#f3f4f5;color:#182027}main{max-width:1500px;margin:auto;padding:32px}h1{font-size:32px;margin-bottom:8px}h2{font-size:23px}p{max-width:950px}nav{position:sticky;top:0;background:#f3f4f5;padding:16px 0;display:flex;gap:12px;border-bottom:1px solid #ccd0d3;z-index:1}a{color:#174b78}nav a{padding:8px 16px;background:white;border:1px solid #ccd0d3;text-decoration:none}section{padding:24px 0;border-bottom:1px solid #ccd0d3;scroll-margin-top:90px}.views{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}img{width:100%;display:block}figcaption{padding-top:8px;color:#4d5961}.files{font-size:14px}@media(max-width:750px){main{padding:16px}.views{grid-template-columns:1fr}}</style><main><h1>Six experiment candidates</h1><p>One task per scene. White SO-101, no robot-mounted camera, fixed front and overhead views.</p><p><strong>Static Blender art previews.</strong> These assets do not establish successful Isaac manipulation or a working application integration. Density and indicator responses require separately labeled analytical models.</p><p><a href="README.md">Import and regeneration instructions</a> · <a href="experiments.json">Conditions and success checks</a> · <a href="validation_summary.json">USD validation</a></p><nav>'''+nav+'</nav>'+''.join(cards)+'</main></html>')
